INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5802, 'CIRI SAMPUL: PRODEO (OTOMATIS; kosong = tidak berlaku)', 'data_sql', 'SELECT IF(IFNULL((SELECT prodeo FROM perkara WHERE perkara_id=#perkara_id#),0)=1,''[&#9632; PRODEO]'','''') AS data', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5802);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5803, 'CIRI SAMPUL: e-COURT (OTOMATIS; kosong = tidak berlaku)', 'data_sql', 'SELECT IF(EXISTS(SELECT 1 FROM perkara_efiling_id WHERE perkara_id=#perkara_id# AND efiling_id<>''''),''[&#9632; e-COURT]'','''') AS data', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5803);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5804, 'CIRI SAMPUL: NON e-COURT (OTOMATIS; kosong = tidak berlaku)', 'data_sql', 'SELECT IF(NOT EXISTS(SELECT 1 FROM perkara_efiling_id WHERE perkara_id=#perkara_id# AND efiling_id<>''''),''[&#9632; NON e-COURT]'','''') AS data', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5804);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5805, 'CIRI SAMPUL: KUASA HUKUM (OTOMATIS; sisi P/T; kosong = tidak berlaku)', 'data_sql', 'SELECT (CASE WHEN x.a AND x.b THEN ''[&#9632; KUASA HUKUM P+T]'' WHEN x.a THEN ''[&#9632; KUASA HUKUM P]'' WHEN x.b THEN ''[&#9632; KUASA HUKUM T]'' ELSE '''' END) AS data FROM (SELECT EXISTS(SELECT 1 FROM perkara_pengacara WHERE perkara_id=#perkara_id# AND pihak_ke=1 AND aktif=''Y'') AS a, EXISTS(SELECT 1 FROM perkara_pengacara WHERE perkara_id=#perkara_id# AND pihak_ke=2 AND aktif=''Y'') AS b) x', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5805);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5806, 'CIRI SAMPUL: KUASA INSIDENTIL (OTOMATIS; kosong = tidak berlaku)', 'data_sql', 'SELECT IF(IFNULL((SELECT TRIM(data) FROM aps_badilag.abt_data_teks WHERE no_var=8537 AND perkara_id=#perkara_id#),'''')<>'''',''[&#9632; KUASA INSIDENTIL]'','''') AS data', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5806);
