INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5814, 'CIRI SAMPUL: DISABILITAS (OTOMATIS; sisi P/T; kosong = tidak berlaku)', 'data_sql', 'SELECT (CASE WHEN x.a AND x.b THEN ''[&#9679; DISABILITAS P+T]'' WHEN x.a THEN ''[&#9679; DISABILITAS P]'' WHEN x.b THEN ''[&#9679; DISABILITAS T]'' ELSE '''' END) AS data FROM (SELECT EXISTS(SELECT 1 FROM perkara_pihak1 k JOIN pihak h ON h.id=k.pihak_id WHERE k.perkara_id=#perkara_id# AND h.difabel=''Y'') AS a, EXISTS(SELECT 1 FROM perkara_pihak2 k JOIN pihak h ON h.id=k.pihak_id WHERE k.perkara_id=#perkara_id# AND h.difabel=''Y'') AS b) x', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5814);
